import React, { useState } from "react";
import { withdraw } from "../../api/bankingApi";
import { getAccountId } from "../../utils/auth";

function Withdraw({ onSuccess, onCancel }) {
  const [amount, setAmount] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const handleWithdraw = async () => {
    if (!amount || parseFloat(amount) <= 0) {
      setMessage("Please enter a valid withdrawal amount.");
      return;
    }
    setLoading(true);
    try {
      await withdraw({
        accountId: parseInt(getAccountId(), 10),
        amount: parseFloat(amount),
      });
      localStorage.setItem("refreshDashboard", "true");
      setAmount("");
      setMessage("");
      onSuccess("Withdrawal successful!");
    } catch (error) {
      console.error("Withdrawal error:", error);
      setMessage("Withdrawal failed. Please try again.");
    }
    setLoading(false);
  };

  return (
    <div>
      {message && (
        <div className="usr-alert usr-alert-danger" style={{ marginBottom: 16 }}>
          {message}
        </div>
      )}
      <div style={{ marginBottom: 16 }}>
        <label style={{ fontSize: 12, fontWeight: 600, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px", display: "block", marginBottom: 6 }}>
          Amount (₹)
        </label>
        <input
          type="number"
          min="0.01"
          step="0.01"
          placeholder="0.00"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && handleWithdraw()}
          style={{
            width: "100%", padding: "10px 14px", borderRadius: 10,
            border: "1.5px solid #e2e8f0", fontSize: 14, color: "#0f172a",
            fontFamily: "Inter, sans-serif", outline: "none",
            transition: "border-color 0.15s",
          }}
          onFocus={(e) => e.target.style.borderColor = "#2563eb"}
          onBlur={(e) => e.target.style.borderColor = "#e2e8f0"}
        />
      </div>
      <div style={{ display: "flex", gap: 10, marginTop: 24 }}>
        <button
          onClick={handleWithdraw}
          disabled={!amount || loading}
          style={{
            flex: 1, padding: "11px", borderRadius: 10, border: "none",
            background: loading ? "#fca5a5" : "#dc2626", color: "#fff",
            fontSize: 14, fontWeight: 600, cursor: loading ? "not-allowed" : "pointer",
            fontFamily: "Inter, sans-serif", transition: "background 0.15s",
          }}
        >
          {loading ? "Processing…" : "Confirm Withdrawal"}
        </button>
        <button
          onClick={onCancel}
          style={{
            padding: "11px 18px", borderRadius: 10, border: "1.5px solid #e2e8f0",
            background: "transparent", color: "#64748b", fontSize: 14,
            fontWeight: 600, cursor: "pointer", fontFamily: "Inter, sans-serif",
          }}
        >
          Cancel
        </button>
      </div>
    </div>
  );
}

export default Withdraw;
